 for(int i=0;i<35;i++){await Task.Delay(20);if(!stillValid())throw new OperationCanceledException("La fenêtre a changé pendant la copie. Aucun remplacement effectué.");uint copied=Native.GetClipboardSequenceNumber();if(copied!=clipOwned){clipOwned=copied;
