 return null;}
 async Task RestoreClipboardAsync(){var backup=clipBackup;uint owned=clipOwned;try{if(clipCaptured)await ClipboardRetry.Run(()=>{if(backup==null)Clipboard.Clear();else Clipboard.SetDataObject(backup,true);return true;},()=>clipCaptured&&Native.GetClipboardSequenceNumber()==owned);}catch{}finally{clipBackup=null;clipCaptured=false;}}
