 async Task CaptureCore(bool rephrase=false,bool generation=false){if(data.Active==null){Balloon("Créez ou importez un personnage dans Personnages.");return;}if(!store.HasKey){Balloon("Ajoutez votre clé API dans Reply AI avant de corriger.");return;}capturing=true;busy=true;IntPtr target=Native.GetForegroundWindow();int version=revision;Func<bool> stillValid=()=>revision==version&&Native.GetForegroundWindow()==target;try{if(!await Released()){ShortcutTrace("Relâchez les touches du raccourci puis réessayez.");return;}if(Native.GetForegroundWindow()!=target){ShortcutTrace("La fenêtre active a changé avant la copie.");return;}uint pid;Native.GetWindowThreadProcessId(target,out pid);var process=System.Diagnostics.Process.GetProcessById((int)pid).ProcessName.ToLowerInvariant();if(new[]{"cmd","powershell","pwsh","windowsterminal","conhost"}.Contains(process)){Balloon("La correction est désactivée dans les terminaux.");return;}
 var probe=Task.Run(()=>{try{var focused=AutomationElement.FocusedElement;if(focused==null)return 0;if(focused.Current.IsPassword)return 2;object pattern;if(focused.TryGetCurrentPattern(TextPattern.Pattern,out pattern)){var selection=((TextPattern)pattern).GetSelection();if(selection.Length==0||selection.All(r=>String.IsNullOrEmpty(r.GetText(-1))))return 1;}return 0;}catch{return 0;}});if(await Task.WhenAny(probe,Task.Delay(180))==probe&&probe.Result!=0){Balloon(probe.Result==2?"Les champs de mot de passe sont exclus.":"Sélectionnez un texte avant de corriger.");return;}if(Native.GetForegroundWindow()!=target)return;
 ShortcutTrace("Copie de la sélection en cours…");uint beforeBackup=Native.GetClipboardSequenceNumber();clipBackup=await ClipboardRetry.Run(()=>Clipboard.GetDataObject(),()=>stillValid()&&Native.GetClipboardSequenceNumber()==beforeBackup);clipOwned=beforeBackup;clipCaptured=true;string text=await CopySelection(stillValid);if(String.IsNullOrWhiteSpace(text)){Balloon("Aucun texte copié. Sélectionnez le message puis réessayez.");return;}if(Native.GetForegroundWindow()!=target)return;ShortcutTrace("Sélection copiée ("+text.Length+" caractères). "+(generation?"Génération":rephrase?"Reformulation":"Correction")+" en cours…");busy=false;var result=await Correct(text,rephrase,generation);lastInput=text;lastOutput=result.Text;lastWarning=result.Warning;lastState=result.Warning??(generation?"Dernière génération depuis le raccourci.":rephrase?"Dernière reformulation depuis le raccourci.":"Dernière correction depuis le raccourci.");if(result.Warning!=null){Balloon("Réponse à vérifier dans Essai RP : "+result.Warning);return;}if(result.Text==text){ShortcutTrace("Le modèle a renvoyé le texte sans modification.");return;}if(revision!=version||Native.GetForegroundWindow()!=target||Native.GetClipboardSequenceNumber()!=clipOwned){Balloon("La correction est prête dans Reply AI. Le contexte ou la fenêtre a changé.");return;}if(!await Released()||Native.GetForegroundWindow()!=target)return;string stillSelected=await CopySelection(stillValid);if(stillSelected!=text||Native.GetForegroundWindow()!=target){Balloon("La sélection a changé. Le résultat reste disponible dans Reply AI.");return;}uint beforePaste=clipOwned;await ClipboardRetry.Run(()=>{Clipboard.SetText(result.Text);clipOwned=Native.GetClipboardSequenceNumber();return true;},()=>stillValid()&&Native.GetClipboardSequenceNumber()==beforePaste);if(!stillValid()||Native.GetClipboardSequenceNumber()!=clipOwned){Balloon("La correction est prête dans Reply AI. La fenêtre ou le presse-papiers a changé.");return;}Native.Key(86);await Task